mapper.select:
SELECT

FROM t_schedule

    status = 1
    AND dept_code = #{deptCode}
    AND doctor_code = #{doctorCode}
    AND work_date = #{workDate}
    AND remaining_num > 0

ORDER BY work_date ASC, period ASC, id ASC

mapper.update:
UPDATE t_schedule
SET remaining_num = LEAST(remaining_num + 1, total_num), version = version + 1, update_time = NOW()
WHERE id = #{id}
